fn xs_next(mut x: u64) -> u64 { x ^= x << 13; x ^= x >> 7; x ^= x << 17; x }
use std::collections::VecDeque;
fn main(){ let nv: usize=50000; let ne: usize=nv*8; let mut adj: Vec<Vec<u32>>=vec![Vec::new(); nv]; let mut r:u64=12345; for _ in 0..ne { r=xs_next(r); adj[(r%nv as u64) as usize].push(((r>>24)%nv as u64) as u32); } let mut dist: Vec<i64>=vec![-1; nv]; let mut q: VecDeque<usize>=VecDeque::new(); let mut total:i64=0; let mut seed:u64=999; for _ in 0..4 { seed=xs_next(seed); let src=(seed%nv as u64) as usize; for v in 0..nv { dist[v]=-1; } q.clear(); dist[src]=0; q.push_back(src); while let Some(u)=q.pop_front() { let d=dist[u]; total+=d; for &w in &adj[u] { let wi=w as usize; if dist[wi]<0 { dist[wi]=d+1; q.push_back(wi); } } } } println!("{}", nv+ne); println!("{}", total); }